import{_ as a,a as t,b as o,c as i,d as n}from"./chunks/3c043b8be0e29575cb01.Cg5OZ2Xy.js";import{_ as l,C as s,o as m,c as f,j as p,a as c,E as h,a6 as u}from"./chunks/framework.CnPv4DE1.js";const x=JSON.parse('{"title":"为什么对失败的恐惧正在毁掉你的生活","description":"","frontmatter":{"title":"为什么对失败的恐惧正在毁掉你的生活","originalTitle":"Why Fear Of Failure Is Ruining Your Life","date":"2022-09-17","originalUrl":"https://thedankoe.com/letters/why-fear-of-failure-is-ruining-your-life/","minutes":9,"sourceHash":"788417c0affabdfc8aebcf24c8497851681aad1a62e0341648a4cc810bd03547","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/why-fear-of-failure-is-ruining-your-life/"}]]},"headers":[],"relativePath":"letters/why-fear-of-failure-is-ruining-your-life.md","filePath":"letters/why-fear-of-failure-is-ruining-your-life.md"}'),d={name:"letters/why-fear-of-failure-is-ruining-your-life.md"};function g(_,e,b,k,y,w){const r=s("ArticleMeta");return m(),f("div",null,[e[0]||(e[0]=p("h1",{id:"为什么对失败的恐惧正在毁掉你的生活",tabindex:"-1"},[c("为什么对失败的恐惧正在毁掉你的生活 "),p("a",{class:"header-anchor",href:"#为什么对失败的恐惧正在毁掉你的生活","aria-label":'Permalink to "为什么对失败的恐惧正在毁掉你的生活"'},"​")],-1)),h(r),e[1]||(e[1]=u('<p><a href="https://www.youtube.com/embed/fvOSd35Snrk?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>学习是人类体验的基础。</p><p>但是，99%的人都做错了。</p><p>不是因为他们不知道如何学习，而是因为他们忘记了如何学习。</p><p>我们这里说的是真正的学习。</p><p>在这封信中，死记硬背、知识囤积和鹦鹉学舌之类的东西都不会被视为学习。</p><p>学习是<em>体验</em>的副产品。</p><p>人类的体验包含的不仅仅是语言。</p><p>它是一系列感觉、光线、声音、味道和其他特征的集合，这些共同形成了一个单一的<em>视角</em>。就像时间里的一个快照。一个在不到一毫秒内流逝的、属于当下意识的虚影。</p><p>语言只是覆盖在现实之上的一层外衣。</p><p>现实由符号、隐喻和能量组成，我们给它们贴上标签，以便理解作为人类我们注意力所关注的事物。</p><p>学习在哪里发挥作用呢？</p><p>挣扎。</p><p>失败。</p><p>那些每个人都避之不及，而不是欣然接受的东西。</p><p>为什么我们要避开它？因为我们不明白失败是什么。不然你为什么要害怕它？我们没有看到全貌，没有完整的视角。而这只能通过失败本身来获得。你明白我的意思了吗？</p><p>既然学习需要失败，请理解这封信是为了唤醒认知而写的。你无法对你没有意识到的事情采取行动，如果这封信让你意识到了失败的重要性，我的任务就完成了。剩下的就掌握在你手中了。我不能代替你失败。</p><p>既然知道人们讨厌他们不理解的东西，那么对于许多人来说，对失败的“讨厌”就是自动的、无意识的，是预先编程好的。</p><p><img src="'+a+'" alt=""></p><p><em>真正学习的第一步是改变你对失败的看法。</em></p><p>也就是说，不去评判、预设，也不去期望它不存在。失败是一种低频能量源。当你专注地介入其中（将那种能量带入你的显意识认知）时，相关的感觉就会在你的存在中显现出来，然后你给那种能量贴上“好”或“坏”的标签。</p><p>失败是存在的。这意味着，如果你不修复你可能已被程序化设定的与失败的关系，拖延和缺乏成就感就会统治你的生活。</p><p>为什么我们必须失败、挣扎并拥抱挑战，才能真正学习？</p><p>因为当你因挣扎而处于一种“糟糕”的意识状态时，你的大脑已经做好了接受教训的准备。它敞开心扉去接受解决方案，将其内化，并将这次学习锁定以备下次使用。</p><p>意思是，你必须直接体验来自挣扎（阻力）的视角，才能让它的对立面（突破）成为现实。</p><p>这种视角要在谷底才能找到。与之相关的感受并不是什么需要避之不及的东西。</p><h2 id="失败的投资组合" tabindex="-1">失败的投资组合 <a class="header-anchor" href="#失败的投资组合" aria-label="Permalink to &quot;失败的投资组合&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>似乎每一个成功人士都会经历一个失败的门槛。</p><p>也就是说，在追求某个特定目标时，一个人必须经历一定数量的失败，然后才能学会成功真正需要什么。</p><p>我个人在赚到第一个1000美元之前，在7种以上的不同商业模式上失败过。</p><p>“Dan，如果可以的话，你会回到过去改变什么吗？”</p><p>被问到这个问题总是很有趣，因为它暗示你想找到那个能避免失败并保持舒适的“秘密”，而实际上失败本身就是那个秘密。</p><p>以我现在的认知，不，我不会回去改变任何事情。如果我改变了，我就必须再次失败，再走一遍那个循环，最后回到完全一样的地方。</p><p>如果我没有在做设计上失败，我就不会去研究如何把设计做得更好的方法。这使得我在Instagram上创建了一个数字艺术页面。</p><p>如果我没有在数字艺术页面上失败，我就不会去学习网页设计。<a href="https://thedankoe.com/i-failed-at-7-online-business-models-and-turned-it-into-a-full-time-creative-income/" target="_blank" rel="noreferrer">这带来了一次又一次的自由职业尝试。</a></p><p>如果我没有在自由职业上失败，我就不会去学习品牌建设、文案写作和社交媒体。这导致了后来电商品牌的失败。</p><p>如果我没有在电商上失败，我就不会得到一份网页设计的工作。这让我在自由职业上取得了成功，转战社交媒体，并一直坚持到现在。</p><p>到了最后，我已经拥有了一个武器库，里面装满在挣扎中提炼出来的教训，足以让我想追求的任何事情都行得通。</p><p><img src="'+o+'" alt=""></p><p>这个模式在任何“白手起家”的成功中都能看到。白手起家的意思是他们没有继承财产。去听听你最喜欢的任何人的起源故事播客，他们都会告诉你同样的故事。失败是不可避免的，是必要的，而且是你所能找到的最接近“一夜暴富”的东西。</p><p>任何努力中的成功，都是一个在你的失败投资组合中投资的过程，<strong>直到再也没有什么可以失败的了****。</strong>也就是说，直到你的投资产生复利，并且你能负担得起成功。</p><p><strong>Koe信件中场广告</strong>：如果你想从我的失败中学习，读者可以花5美元加入<a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Modern Mastery</a>。那里有180多项策略，你可以去测试、去失败，从而更快地建立你的失败投资组合。</p><h2 id="如何快乐地失败-已知与未知的交汇点" tabindex="-1">如何快乐地失败：已知与未知的交汇点 <a class="header-anchor" href="#如何快乐地失败-已知与未知的交汇点" aria-label="Permalink to &quot;如何快乐地失败：已知与未知的交汇点&quot;">​</a></h2><p>人类在故事中寻找意义。</p><p>故事是我们理解世界的方式。</p><p>在我们不知不觉中，我们的潜意识会“填补”我们所感知到的任何事物的“空白”。</p><p>当你接近一个陌生人时，为什么会感到焦虑？因为你的大脑已经判定了结果。</p><p>当你做某一件具体的事情，比如在健身房做同样的动作太久，你为什么会觉得无聊？因为你的大脑已经知道要做什么了。</p><p>生活是一场包含无限多场游戏的游戏。</p><p>你选择玩什么游戏，将决定你从赢得这些游戏中获得什么结果。</p><p>问题出在哪里？</p><p>游戏意味着有可能失败。</p><p>更有甚者，当你开始持续玩一款新游戏时，你“失败”的次数会更多。你不可能靠赢下每一场比赛，就直接从1级升到100级。</p><blockquote><p>阳刚之气想要感受生活在边缘的狂喜，如果他没有胆量自己去尝试，他就会在电视上，在体育赛事和警匪片中观看它。—— 大卫·戴达（David Deida）</p></blockquote><p>游戏是令人兴奋的。它们是你主动参与的结构化故事。这就是你在生活中找到意义的方式：沉迷于那些能带来成就感结果的游戏中。</p><p><em>关于</em> <em>这段引言，不要把“阳刚之气”（the masculine）与男性或女性混为一谈。每个人都有阳刚和阴柔的一面。</em> <em>这是一种在现实中展现出不同特征的能量形式，不仅存在于人类身上</em>_。_</p><p>重点在于，追求更多、征服以及从赢得战斗中获得的好处，这就是阳刚。</p><p>男人和女人都一样，特别是随着技术解决了一些问题，女人开始承担更多阳刚的活动（男人也反之亦然），每个人都可以：</p><ul><li>在职场阶梯上攀登</li><li>围绕他们的兴趣建立企业</li><li>在充满挑战的体育比赛中竞争</li></ul><p>认为男人能够或者应该做到100%阳刚，或者女人能够或者应该做到100%阴柔，是愚蠢的。每个人内心都有需要保持的平衡。大多数男人偏向于阳刚，而女人则反之亦然。</p><p>这个话题我改天再谈，但这个世界正在融合。有人预测，它将坍缩为一体。我不在乎人们的身份认同是什么，我只是喜欢观察并把事情拼凑起来（而不是让它把我激怒，甚至把我的身份认同建立在摧毁这些事情上）。</p><p>我在建设时（阳刚）充满活力，但我也知道什么时候该放松和庆祝（阴柔）。秩序与混乱。这是隐喻，而不是字面意思。</p><p>热了，你就降温。冷了，你就取暖。有些人大部分时间喜欢暖和，有些人喜欢冷。当男人们在生意上大获全胜时，他们会喝啤酒庆祝。这就是平衡。</p><p>关键在于，想要过上有成就感的生活，每个人内心阳刚的一面都需要通过参与战斗来维持平衡。也就是说，玩一场游戏。这里面需要有悬念。即使你不认为自己有“阳刚的一面”，忽视你生命中的这一面也是不明智的。</p><p>阴与阳。</p><blockquote><p>当一个人应对某个情境的挑战需要运用其所有相关技能时，这个人的注意力会被这项活动完全吸收。没有任何多余的心理能量留下来处理除了活动提供的信息之外的任何信息。所有的注意力都集中在相关的刺激上。—— 米哈里·契克森米哈赖（Mihaly Csikszentmihalyi）</p></blockquote><p>战斗发生在战场上。</p><p>游戏要在特定的规则下进行。</p><p>任何现实生活中的情况，都会呈现出一个带有某些已知和未知变量的<em>环境</em>。</p><p><em>如果你不知道怎么玩这个游戏，它就不会好玩。</em> <em><strong>你会感到焦虑。</strong></em></p><p>健身房里的菜鸟不会尝试去硬拉400磅。他会接受自己当前力量的挑战，并对未来几个月的进步感到兴奋。</p><p><em>如果你太擅长这个游戏，它也不会好玩。<strong>你会感到无聊。</strong></em></p><p>国际象棋大师可能会从教导初学者带来的挑战中找到乐趣，但和初学者下棋呢？<strong>很无聊</strong>。大师的技能必须受到考验，他才能进入心流状态。<a href="https://thedankoe.com/why-you-always-feel-overwhelmed/" target="_blank" rel="noreferrer">他的注意力才能沉浸在他正在追求的目标中</a>。</p><p><img src="'+i+'" alt=""></p><p><em>舒适存在于已知之中。</em></p><p><em>不适存在于未知之中。</em></p><p><em>成就感存在于边界之上。</em></p><p><img src="'+n+'" alt=""></p><p>我确信这就是古人在解释“无念”或“不二”时所说的一部分含义。</p><p>一种类似于现代心理学家所创造的“心流”概念的意识状态。</p><p>这跟失败有什么关系？</p><p>通过追求正确的目标，你可以享受更频繁的失败。</p><p><em>一个既不会遥远到让你在未知中迷失，又不会近到让你感到无聊的目标。</em></p><p>同时，还能因其价值而得到认可。</p><p>在我们结束之前，问一个问题：</p><p>你的愿景对你来说足够有价值吗？</p><p>也就是说，你是否<em>内化、欣赏并深度思考</em>过，实现这个愿景将如何溢出并影响你的生活？</p><p>财务自由值得10年的<em>失败</em>吗？如果不是，还有别的选择吗？那别的选择值得你挣扎10年吗？</p><p>重复这一连串的问题。把“财务自由”换成任何好东西。那些不能外包或无法别人直接给你的东西，比如：</p><ul><li>你的体格和能量水平</li><li>你用一生建立的品牌</li><li>精通你的手艺以及你在世上行事的方式</li></ul><p>把它写下来。在散步时沉思你的未来。让你的愿景随着<em>时间</em>变得清晰。它不是一蹴而就的。</p><p>和它待在一起静静体会。</p><p><strong>你不需要更多的建议</strong></p><p>寻求建议，就是把你采取行动并自行解决问题的能力外包出去。</p><p>（寻求建议不同于为你正在执行的行动获取特定信息，那叫教育，是另一件需要投入数十年的事）。</p><p>回头看看那张图。</p><p>你其实已经<em>知道</em>你需要去执行什么。</p><p>你需要把自己推向已知的边缘，挑战自我，品尝未知的滋味，并对你真正不懂的事物（以及它们何时最适用）进行教育投资。</p><p><em>“我应该创业吗？”</em></p><p><em>“我应该去健身房吗？”</em></p><p><em>“我应该约那个人出去吗？”</em></p><p>如果我告诉你“是”，你能学到什么吗？如果我告诉你“不”呢？</p><p>如果你听从了其中任何一个，你就无法亲自在未知中寻找答案。你可能会因为别人叫你别做某事而白白浪费 2-3 年时间，而不是自己去尝试并弄个明白。</p><p>去构建，去创造，去挑战自己，尝试一切，然后找到答案。</p><p>这就是人类的做法。</p><p>– Dan Koe</p><h3 id="本周动态" tabindex="-1">本周动态 <a class="header-anchor" href="#本周动态" aria-label="Permalink to &quot;本周动态&quot;">​</a></h3><p>发布了一期新播客，探讨写作这项每个人都该学习的元技能。</p><p><a href="https://open.spotify.com/episode/0HLHWwyXRJtLYFFYH6GfdE?si=d116a17ed5c7460c" target="_blank" rel="noreferrer">点击这里收听。</a></p><p>上线了一期 YouTube 视频，探讨为什么人们无法通过做自己的事情赚钱。</p><p><a href="https://youtu.be/ijU4OTfzu8Y" target="_blank" rel="noreferrer">点击这里观看。</a></p><p>周三我将发文分享我是如何把我的推文做成 Instagram 轮播图的（以及如何将这些轮播图发布到 LinkedIn 以获得更多互动）。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者仅需 $5 即可加入。</a></p><p><em><strong>当你准备好时，你可以在下方找到更多免费和付费资源，用于建设你自己和你的企业</strong></em><em><strong>。</strong></em></p><hr><p><a href="/en/letters/why-fear-of-failure-is-ruining-your-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',117))])}const I=l(d,[["render",g]]);export{x as __pageData,I as default};
